```c
/**
 * Set up the copy-on-write diff file for a client. Called when a
 * client connects to a copy-on-write export; the diff file is where
 * all writes for this connection will be stored, so that the exported
 * file itself remains untouched.
 *
 * @param client The client for which to set up the diff file
 * @return true on success, false on failure
 **/
static bool setup_cow(CLIENT* client) {
	_cleanup_g_free_ gchar *dir = NULL;
	_cleanup_g_free_ gchar *base = NULL;

	if(client->server->cowdir) {
		dir = g_strdup(client->server->cowdir);
	} else {
		dir = g_path_get_dirname(client->exportname);
	}
	base = g_path_get_basename(client->exportname);
	client->difffilename = g_strdup_printf("%s/%s.%s.%d.diff", dir, base, client->clientname, (int)getpid());
	client->difffile = open(client->difffilename, O_RDWR | O_CREAT | O_TRUNC, 0600);
	if(client->difffile < 0) {
		err_nonfatal("Could not open copy-on-write diff file %s: %m");
		g_free(client->difffilename);
		client->difffilename = NULL;
		return false;
	}
	if(client->server->flags & F_SPARSE) {
		if(ftruncate(client->difffile, client->exportsize) < 0) {
			err_nonfatal("Could not grow copy-on-write diff file %s: %m");
			close(client->difffile);
			client->difffile = -1;
			unlink(client->difffilename);
			g_free(client->difffilename);
			client->difffilename = NULL;
			return false;
		}
	}
	client->difmap = g_hash_table_new_full(g_int64_hash, g_int64_equal, g_free, g_free);
	if(pthread_mutex_init(&client->diff_lock, NULL)) {
		msg(LOG_ERR, "Unable to initialize copy-on-write mutex");
		g_hash_table_destroy(client->difmap);
		client->difmap = NULL;
		close(client->difffile);
		client->difffile = -1;
		unlink(client->difffilename);
		g_free(client->difffilename);
		client->difffilename = NULL;
		return false;
	}
