```c
/*
 * Copy-on-write support.
 *
 * When an export is exported in copy-on-write mode, writes are not
 * done on the exported ("master") file. Instead, every page that is
 * written is stored in a diff file which is specific to the current
 * connection, and reads of such pages return the contents of the diff
 * file rather than those of the master file. When the client
 * disconnects, the diff file is removed, so all writes performed
 * during the connection are discarded and the master file is left
 * untouched.
 *
 * If the sparse_cow option is set, the diff file is a sparse file as
 * large as the export, and pages are stored at their corresponding
 * offset. Otherwise, every newly written page is appended to the end
 * of the diff file, and difmap remembers where each page can be found.
 */

/**
 * Read an amount of bytes at a given offset from the right file. This
 * abstracts the read-side of the multiple files option.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
static ssize_t read_export(off_t a, char *buf, size_t len, CLIENT *client) {
	int fhandle;
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;

	if(get_filepos(client, a, &fhandle, &foffset, &maxbytes))
		return -1;
	if(maxbytes && len > maxbytes)
		len = maxbytes;

	DEBUG("(READ from fd %d offset %llu len %u), ", fhandle, (long long unsigned int)foffset, (unsigned int)len);

	retval = pread(fhandle, buf, len, foffset);
        if (client->server->flags & F_TREEFILES) {
		close(fhandle);
	}
	return retval;
}
