```c
/**
 * Write an amount of bytes at a given offset to the copy-on-write diff
 * file. Pages that are only partially written are first filled up with
 * the current contents of the export, so that a page stored in the
 * diff file always contains the complete contents of that page.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes written, or -1 in case of an error
 **/
static ssize_t cow_write(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	char page[DIFFPAGESIZE];
	size_t done = 0;

	while(done < len) {
		off_t pos = a + done;
		uint64_t pagenr = pos / DIFFPAGESIZE;
		off_t pageoff = pos % DIFFPAGESIZE;
		size_t chunk = len - done;
		off_t diffpos;
		bool newpage;

		if(chunk > (size_t)(DIFFPAGESIZE - pageoff))
			chunk = DIFFPAGESIZE - pageoff;

		pthread_mutex_lock(&client->diff_lock);
		diffpos = difmap_lookup(client, pagenr);
		newpage = (diffpos < 0);
		if(newpage) {
			if(client->server->flags & F_SPARSE) {
				diffpos = pagenr * DIFFPAGESIZE;
			} else {
				diffpos = client->difffilelen;
			}
		}
		if(newpage && (pageoff || chunk != DIFFPAGESIZE)) {
			/* The page is only partially written, so fill in
			 * the remainder with the current contents of the
			 * export before writing it to the diff file */
			memset(page, 0, DIFFPAGESIZE);
			if(read_export_fully(pagenr * DIFFPAGESIZE, page, DIFFPAGESIZE, client) < 0) {
				pthread_mutex_unlock(&client->diff_lock);
				return -1;
			}
			memcpy(page + pageoff, buf + done, chunk);
			if(pwrite_fully(client->difffile, page, DIFFPAGESIZE, diffpos) < 0) {
				pthread_mutex_unlock(&client->diff_lock);
				return -1;
			}
		} else if(newpage) {
			if(pwrite_fully(client->difffile, buf + done, DIFFPAGESIZE, diffpos) < 0) {
				pthread_mutex_unlock(&client->diff_lock);
				return -1;
			}
		} else {
			if(pwrite_fully(client->difffile, buf + done, chunk, diffpos + pageoff) < 0) {
				pthread_mutex_unlock(&client->diff_lock);
				return -1;
			}
		}
		if(newpage) {
			if(!(client->server->flags & F_SPARSE)) {
				client->difffilelen += DIFFPAGESIZE;
			}
			difmap_insert(client, pagenr, diffpos);
		}
		pthread_mutex_unlock(&client->diff_lock);
		done += chunk;
	}
	if(client->server->flags & F_SYNC) {
		fsync(client->difffile);
	} else if(fua) {
		fdatasync(client->difffile);
	}
	return len;
}
```

Wait — `read_export_fully`: I need a helper that reads fully from the master (looping over read_export for multifile boundaries). Let me define it:

```c
/**
 * Call read_export repeatedly until all data has been read or the end
 * of the export is reached.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return 0 on success, -1 on failure
 **/
static int read_export_fully(off_t a, char *buf, size_t len, CLIENT *client) {
	while(len > 0) {
		ssize_t ret = read_export(a, buf, len, client);
		if(ret < 0)
			return -1;
		if(ret == 0)
			break;
		a += ret;
		buf += ret;
		len -= ret;
	}
	return 0;
