static CLIENT *cow_atexit_client = NULL;

/**
 * atexit() handler that removes the copy-on-write diff file, so that
 * it is cleaned up even if we exit without going through
 * finalize_client().
 **/
static void cow_atexit_cleanup(void) {
	if(cow_atexit_client) {
		cleanup_cow(cow_atexit_client);
		cow_atexit_client = NULL;
	}
}

/**
 * Remove the copy-on-write diff file of a client, if any. All data
 * written during the connection is stored in the diff file only, so
 * removing it discards those writes and leaves the exported file as
 * it was.
 *
 * @param client The client whose diff file should be removed
 **/
static void cleanup_cow(CLIENT *client) {
	if(client->difffilename) {
		if(unlink(client->difffilename) < 0) {
			msg(LOG_INFO, "Could not remove copy-on-write diff file %s: %m", client->difffilename);
		} else {
			msg(LOG_INFO, "Removed copy-on-write diff file %s", client->difffilename);
		}
		g_free(client->difffilename);
		client->difffilename = NULL;
	}
	if(client->difffile >= 0) {
		close(client->difffile);
		client->difffile = -1;
	}
	if(client->difmap) {
		g_hash_table_destroy(client->difmap);
		client->difmap = NULL;
		pthread_mutex_destroy(&client->diff_lock);
	}
}

/**
