/**
 * Write an amount of bytes to a file descriptor at a given offset,
 * retrying partial writes.
 *
 * @param fd The file descriptor to write to
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param off The offset to write at
 * @return 0 on success, -1 on failure
 **/
static int pwrite_fully(int fd, char *buf, size_t len, off_t off) {
	while(len > 0) {
		ssize_t ret = pwrite(fd, buf, len, off);
		if(ret < 0) {
			if(errno == EINTR)
				continue;
			return -1;
		}
		buf += ret;
		off += ret;
		len -= ret;
	}
	return 0;
}

/**
 * Read an amount of bytes from a file descriptor at a given offset,
 * retrying partial reads.
 *
 * @param fd The file descriptor to read from
 * @param buf The buffer to read into
 * @param len The size of buf
 * @param off The offset to read from
 * @return The number of bytes read, which may be less than len if the
 * end of the file was reached, or -1 on failure
 **/
static ssize_t pread_fully(int fd, char *buf, size_t len, off_t off) {
	size_t done = 0;

	while(done < len) {
		ssize_t ret = pread(fd, buf + done, len - done, off + done);
		if(ret < 0) {
			if(errno == EINTR)
				continue;
			return -1;
		}
		if(ret == 0)
			break;
		done += ret;
	}
	return done;
}

/**
 * Write an amount of bytes at a given offset to the copy-on-write diff
 * file. Pages that are only partially written are first filled up with
 * the current contents of the export, so that a page stored in the
 * diff file always contains the complete contents of that page.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
