/*
 * Copy-on-write support.
 *
 * When an export is exported in copy-on-write mode, writes do not go
 * to the exported ("master") file. Instead, every page that is
 * written is stored in a diff file that is specific to the current
 * connection, and reads of such pages return the contents of the diff
 * file rather than those of the master file. When the client
 * disconnects, the diff file is removed, so all writes performed
 * during the connection are discarded and the master file is left
 * untouched.
 *
 * If the sparse_cow option is set, the diff file is created as a
 * sparse file that is as large as the export, and pages are stored at
 * the offset corresponding to their position in the export. If not,
 * every newly written page is appended to the end of the diff file,
 * and difmap remembers where each page can be found.
 */

/**
 * Read an amount of bytes at a given offset from the exported
 * file(s), bypassing the copy-on-write diff file.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an
 * error.
 **/
static ssize_t read_export(off_t a, char *buf, size_t len, CLIENT *client) {
	int fhandle;
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;

	if(get_filepos(client, a, &fhandle, &foffset, &maxbytes))
		return -1;
	if(maxbytes && len > maxbytes)
		len = maxbytes;

	DEBUG("(READ from fd %d offset %llu len %u), ", fhandle, (long long unsigned int)foffset, (unsigned int)len);

	retval = pread(fhandle, buf, len, foffset);
        if (client->server->flags & F_TREEFILES) {
		close(fhandle);
	}
	return retval;
}

/**
 * Call read_export repeatedly until all data has been read or the end
 * of the export is reached.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return 0 on success, -1 on failure
 **/
static int read_export_fully(off_t a, char *buf, size_t len, CLIENT *client) {
	while(len > 0) {
		ssize_t ret = read_export(a, buf, len, client);
		if(ret < 0)
			return -1;
		if(ret == 0)
			break;
		a += ret;
		buf += ret;
		len -= ret;
	}
	return 0;
}

/**
 * Find the position of a page in the copy-on-write diff file.
 *
 * @param client The client we're serving for
 * @param page The page number to look up
 * @return The position of the page in the diff file, or -1 if the
 * page is not present in the diff file.
 **/
static off_t difmap_lookup(CLIENT *client, uint64_t page) {
	gint64 *value;

	value = g_hash_table_lookup(client->difmap, &page);
	if(!value)
		return -1;
	return *value;
}

/**
 * Record that a page is present in the copy-on-write diff file.
 *
 * @param client The client we're serving for
 * @param page The page number
 * @param pos The position of the page in the diff file
 **/
static void difmap_insert(CLIENT *client, uint64_t page, off_t pos) {
	gint64 *key = g_new(gint64, 1);
	gint64 *value = g_new(gint64, 1);

	*key = page;
	*value = pos;
	g_hash_table_insert(client->difmap, key, value);
}

/** The client whose diff file must be removed upon exit, if any */
static CLIENT *cow_atexit_client = NULL;

/**
 * atexit() handler that removes the copy-on-write diff file, so that
 * it is cleaned up even if we exit without going through
 * finalize_client().
 **/
static void cow_atexit_cleanup(void) {
	if(cow_atexit_client) {
		cleanup_cow(cow_atexit_client);
		cow_atexit_client = NULL;
	}
}

/**
 * Remove the copy-on-write diff file of a client, if any. All data
 * written during the connection is stored in the diff file only, so
 * removing it discards those writes and leaves the exported file as
 * it was.
 *
 * @param client The client whose diff file should be removed
 **/
static void cleanup_cow(CLIENT *client) {
	if(client->difffilename) {
		if(unlink(client->difffilename) < 0) {
			msg(LOG_INFO, "Could not remove copy-on-write diff file %s: %m", client->difffilename);
		} else {
			msg(LOG_INFO, "Removed copy-on-write diff file %s", client->difffilename);
		}
		g_free(client->difffilename);
		client->difffilename = NULL;
	}
	if(client->difffile >= 0) {
		close(client->difffile);
		client->difffile = -1;
	}
	if(client->difmap) {
		g_hash_table_destroy(client->difmap);
		client->difmap = NULL;
		pthread_mutex_destroy(&client->diff_lock);
	}
}

/**
 * Set up the copy-on-write diff file for a client. Called when a
 * client connects to a copy-on-write export.
 *
 * @param client The client for which to set up the diff file
 * @return true on success, false on failure
 **/
static bool setup_cow(CLIENT* client) {
	_cleanup_g_free_ gchar *dir = NULL;
	_cleanup_g_free_ gchar *base = NULL;

	if(client->server->cowdir) {
		dir = g_strdup(client->server->cowdir);
	} else {
		dir = g_path_get_dirname(client->exportname);
	}
	base = g_path_get_basename(client->exportname);
	client->difffilename = g_strdup_printf("%s/%s.%s.%d.diff", dir, base,
			client->clientname, (int)getpid());
	client->difffile = open(client->difffilename, O_RDWR | O_CREAT | O_TRUNC, 0600);
	if(client->difffile < 0) {
		err_nonfatal("Could not open copy-on-write diff file %s: %m");
		cleanup_cow(client);
		return false;
	}
	if((client->server->flags & F_SPARSE) &&
			ftruncate(client->difffile, client->exportsize) < 0) {
		err_nonfatal("Could not grow copy-on-write diff file %s: %m");
		cleanup_cow(client);
		return false;
	}
	client->difmap = g_hash_table_new_full(g_int64_hash, g_int64_equal, g_free, g_free);
	if(pthread_mutex_init(&client->diff_lock, NULL)) {
		msg(LOG_ERR, "Unable to initialize copy-on-write mutex");
		cleanup_cow(client);
		return false;
	}
	if(!cow_atexit_client) {
		atexit(cow_atexit_cleanup);
	}
	cow_atexit_client = client;
	msg(LOG_INFO, "Storing copy-on-write differences in %s", client->difffilename);
	return true;
}

